import * as React from "react";

export type CoinDoubleIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function CoinDoubleIcon({ size = 20, ...props }: CoinDoubleIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <circle cx={9.5} cy={10} r={5.5} />
      <circle cx={14.5} cy={14} r={5.5} />
    </svg>
  );
}
